# -*- coding: utf-8 -*-
"""Danh sách ảnh lấy ĐÚNG TÊN mà các cụm gọi trong cột ảnh tham chiếu của kịch bản.

Kịch bản đặt tên ảnh theo lối riêng (ví dụ WHITE WOLVES):
  M01, L02, G01           -> bộ trang phục (mã trang phục, không có tiền tố)
  CHAR_MARA_FACE, LYRA_FACE -> mặt nhân vật (có hoặc không có CHAR_)
  CHAR_MARA_FACE_2 / _3   -> các góc phụ của mặt
  CHAR_MARA_FACE_SHEET    -> ảnh ghép 3 góc từ các ảnh trên
  LOC_MARA_HOME_INT_1..3  -> các góc máy của một bối cảnh
  W_ALPHA, W_PACK         -> sinh vật
  PROP_LANTERN            -> đạo cụ
  BRIDGE_C001_END         -> khung cuối của cụm trước, lấy từ video chứ không gen
Mỗi tên được gắn về đúng đối tượng trong kịch bản để lấy prompt; tên nào không gắn được thì báo ra, không bịa."""
import re

GOC_MAT = {'': 'front view, head and shoulders, looking at camera',
           '2': 'three-quarter view, head and shoulders, turned slightly to the left',
           '3': 'profile view, head and shoulders, facing right'}
GOC_CANH = {'1': 'wide establishing view', '2': 'reverse angle from the opposite side',
            '3': 'closer medium view of the main area'}


def _phan_tach(ten):
    """-> (gốc, hậu tố góc, là_sheet)"""
    sheet = ten.endswith('_SHEET')
    goc = ten[:-6] if sheet else ten
    m = re.match(r'^(.*?)_(\d)$', goc)
    return (m.group(1), m.group(2), sheet) if m else (goc, '', sheet)


def gan_ten(ten, da):
    """Tên ảnh -> {'loai', 'doi_tuong', 'goc', 'sheet'} hoặc None nếu không hiểu."""
    if ten.startswith('BRIDGE_'):
        return {'loai': 'khung_noi', 'doi_tuong': ten, 'goc': '', 'sheet': False}
    goc, so, sheet = _phan_tach(ten)
    if goc.startswith('BRIDGE_'):
        return {'loai': 'khung_noi', 'doi_tuong': goc, 'goc': so, 'sheet': False}
    nv = da.get('nhan_vat', {})
    m = re.match(r'^(?:CHAR_)?([A-Z0-9_]+?)_FACE(?:_(\d{2,}))?$', goc)
    if m and m.group(1) in nv:
        return {'loai': 'mat', 'doi_tuong': m.group(1), 'goc': m.group(2) or so, 'sheet': sheet}
    for t, v in nv.items():                                   # mã trang phục: M01, OUTFIT_M01, LYRA_L00…
        do = v.get('do') or {}
        for ma in (goc, goc.replace('OUTFIT_', ''), goc[len(t) + 1:] if goc.startswith(t + '_') else None):
            if ma and ma in do:
                return {'loai': 'trang_phuc', 'doi_tuong': t, 'ma': ma, 'goc': so, 'sheet': sheet}
    le = da.get('trang_phuc_le') or {}                        # trang phục của nhân vật không có ảnh mặt (lính, dân làng)
    if goc in le or goc.replace('OUTFIT_', '') in le:
        return {'loai': 'trang_phuc_le', 'doi_tuong': goc.replace('OUTFIT_', ''), 'goc': so, 'sheet': sheet}
    bc = da.get('boi_canh', {})
    ma_bc = goc.replace('LOC_', '')
    if goc.startswith('LOC_') and ma_bc in bc:
        return {'loai': 'boi_canh', 'doi_tuong': ma_bc, 'goc': so, 'sheet': sheet}
    dc = da.get('dao_cu', {})
    for k in (goc, goc.replace('PROP_', ''), goc.replace('CREATURE_', '')):
        if k in dc:
            return {'loai': 'dao_cu', 'doi_tuong': k, 'goc': so, 'sheet': sheet}
    return None


def _prompt_co_san(da, *ten_thu):
    """Prompt nguyên văn từ danh sách ảnh đọc trong file (nếu có)."""
    theo = {a.get('ten'): a for a in (da.get('anh_can_gen') or [])}
    for t in ten_thu:
        if t in theo and theo[t].get('prompt'): return theo[t]['prompt']
    return ''


def khoa_doi_tuong(g):
    """Hai tên khác nhau nhưng cùng một ảnh (M01 và OUTFIT_M01) thì cùng khoá."""
    if not g: return None
    return (g['loai'], g['doi_tuong'], g.get('ma', ''), g.get('goc', ''), g.get('sheet', False))


def dung(da):
    """-> ({tên: {prompt, size, goc, loai, ghep_tu}}, [tên không gắn được])"""
    pc = da.get('phong_cach') or 'Photoreal live-action film production reference photo.'
    ten_goi = []
    for c in da.get('cum', []):
        for r in c.get('refs', []):
            if r not in ten_goi: ten_goi.append(r)
    ra, khong_gan = {}, []
    theo_ten = {a.get('ten'): a for a in (da.get('anh_can_gen') or [])}
    TI = {'2:3': '1024x1536', '3:4': '1024x1536', '16:9': '1536x1024', '4:3': '1536x1024', '1:1': '1024x1024'}
    for ten in ten_goi:
        if ten in theo_ten and theo_ten[ten].get('prompt') and not ten.endswith('_SHEET'):
            a = theo_ten[ten]; g = gan_ten(ten, da) or {}
            goc_anh = a.get('goc')
            if g.get('loai') == 'trang_phuc':                  # áo lấy ảnh mặt đầu tiên cụm dùng làm gốc
                goc_anh = next((k for k in ten_goi if re.match(rf"^(?:CHAR_)?{g['doi_tuong']}_FACE(?:_01)?$", k)), goc_anh)
            ra[ten] = {'loai': g.get('loai') or a.get('nhom', ''), 'prompt': a['prompt'], 'goc': goc_anh,
                       'size': TI.get(str(a.get('ti_le')), '1024x1536')}
            continue
        g = gan_ten(ten, da)
        if not g:
            khong_gan.append(ten); continue
        loai, dt, so = g['loai'], g['doi_tuong'], g['goc']
        khoa = khoa_doi_tuong(g)
        if loai == 'khung_noi':
            ra[ten] = {'loai': 'khung_noi', 'prompt': '', 'size': '1536x1024', 'goc': None,
                       'ghi_chu': 'lấy khung cuối video cụm trước lúc gen, không tạo ảnh'}
            continue
        if g['sheet']:                                          # ảnh ghép 3 góc từ các ảnh cùng gốc
            goc_ten = ten[:-6]
            ra[ten] = {'loai': 'sheet', 'prompt': '', 'size': '3072x1536', 'goc': None,
                       'ghep_tu': [goc_ten, goc_ten + '_2', goc_ten + '_3']}
            for i, t in enumerate(ra[ten]['ghep_tu']):          # đảm bảo có đủ 3 góc để ghép
                if t not in ten_goi: ten_goi.append(t)
            continue
        if loai == 'mat':
            nv = da['nhan_vat'][dt]
            goc_prompt = (_prompt_co_san(da, f'CHAR_{dt}_FACE', f'{dt}_FACE') or
                          f"{pc} Portrait of {dt.title().replace('_', ' ')}, {nv.get('tuoi', '')} years old: "
                          f"{nv.get('mo_ta', '')}.")
            ra[ten] = {'loai': 'mat', 'size': '1024x1536', 'goc': None,
                       'prompt': goc_prompt + ' Camera: ' + GOC_MAT.get(so, GOC_MAT['']) +
                                 '. Plain neutral studio background, one subject only, no text, no watermark.'}
        elif loai == 'trang_phuc':
            ma = g['ma']; nv = da['nhan_vat'][dt]
            p = (_prompt_co_san(da, f'OUTFIT_{ma}', ma) or
                 f"Use the uploaded reference as the exact face and hair of {dt.title()}. Full-body costume reference, "
                 f"head to shoes inside frame. Outfit {ma}: {nv['do'].get(ma, '')}. {pc}")
            mat = next((k for k in ten_goi if re.match(rf'^(?:CHAR_)?{dt}_FACE(?:_01)?$', k)), None) or                   next((k for k in ten_goi if re.match(rf'^(?:CHAR_)?{dt}_FACE', k)), None)
            if not mat:                                           # cụm không gọi mặt người này: lấy mặt đầu tiên trong file
                mat = next((a['ten'] for a in (da.get('anh_can_gen') or [])
                            if re.match(rf'^(?:CHAR_)?{dt}_FACE', str(a.get('ten')))), f'CHAR_{dt}_FACE')
            ra[ten] = {'loai': 'trang_phuc', 'size': '1024x1536', 'goc': mat, 'prompt': p}
            if mat not in ten_goi: ten_goi.append(mat)          # ảnh mặt làm gốc phải có trước
        elif loai == 'trang_phuc_le':
            ma = dt; le = da.get('trang_phuc_le') or {}
            p = _prompt_co_san(da, f'OUTFIT_{ma}', ma) or f"Full-body costume reference, head to shoes inside frame: {le.get(ma, '')}. {pc}"
            ra[ten] = {'loai': 'trang_phuc', 'size': '1024x1536', 'goc': None, 'prompt': p}
        elif loai == 'boi_canh':
            b = da['boi_canh'][dt]
            p = (_prompt_co_san(da, f'LOC_{dt}') or
                 f"{pc} Environment plate, no people: {b.get('mo_ta', '')}. {b.get('anh_sang', '')}")
            ra[ten] = {'loai': 'boi_canh', 'size': '1536x1024', 'goc': None,
