ảnh trong .refs có thật, ≤ 9 · không tên trơn ngoài thoại · mốc giây liền 0–30 · chữ cấm (chung + trang phục Bianca) · độ dài."""
import re, sys
from pathlib import Path

GOC = Path(__file__).resolve().parents[3]                      # thư mục tác phẩm
ZH = Path(__file__).resolve().parent
ANH = ZH.parent / 'anh'
KB = GOC / '04_kich-ban-chinh-thuc.md'
TEN = ['BEVERLY', 'AYANNA', 'DARIUS', 'BIANCA', 'EARNESTINE', 'CHARLENE', 'NADINE', 'TAMIA', 'LATASHA', 'IMES',
       'DRIVER', 'OFFICER', 'LOCKSMITH']
KHOI = ['参考图识别说明', '【场景图】', '【人物参考图】', '【人物位置】', '30秒', '镜头语言', '[保持不变]', '结尾时']
CAM = ['血', '枪', '杀', '暴力', '性感', '低胸', '胸']
CAM_BIANCA = ['抹胸', '露肩', '身材', '曲线', '紧身', '包臀', '迷你', '短裙', '大腿', '臀']


def thoai_kich_ban():
    t = KB.read_text(encoding='utf-8')
    ra = {}
    for b in re.split(r'^(?=#### Cụm )', t, flags=re.M):
        m = re.match(r'#### Cụm (\d+)', b)
        if not m: continue
        ra[int(m.group(1))] = [x for x in re.findall(r'^- \*\*[A-Z][A-Z .\'-]*?:?\*\*[^"\n]*"(.+)"\s*$', b, flags=re.M)]
    return ra


def chuan(s):
    return s.replace('’', "'").replace('‘', "'").replace('“', '"').replace('”', '"').replace('…', '...').strip()


def soat(n, kb):
    loi, canh = [], []
    f = ZH / 'prompt' / f'cum_{n:03d}.txt'
    fr = ZH / 'prompt' / f'cum_{n:03d}.refs'
    if not f.exists(): return ['THIẾU bài'], []
    if not fr.exists(): return ['THIẾU .refs'], []
    t = f.read_text(encoding='utf-8-sig')
    refs = [x.strip() for x in fr.read_text(encoding='utf-8-sig').splitlines() if x.strip()]
    if len(refs) > 9: loi.append(f'{len(refs)} ảnh > 9')
    for r in refs:
        if not (ANH / f'{r}.png').exists(): loi.append(f'không có ảnh {r}.png')
    for k in KHOI:
        if k not in t: loi.append(f'thiếu khối {k}')
    # thoại
    th = re.findall(r'\{([^{}]*)\}', t)
    th = [x for x in th if not re.fullmatch(r'[^A-Za-z]*', x)]           # bỏ {} không phải thoại (nếu có)
    for x in th:
        if '"' in x or '“' in x: loi.append(f'thoại còn ngoặc kép: {x[:40]}')
    can = [chuan(x) for x in kb.get(n, [])]
    co = [chuan(x).strip('"') for x in th]
    if co != can:
        loi.append(f'thoại lệch kịch bản: bài {len(co)} câu, kịch bản {len(can)} câu')
        for i, (a, b) in enumerate(zip(co, can)):
            if a != b: loi.append(f'  câu {i+1}: bài «{a}» ≠ kb «{b}»'); break
    so = {'一': 1, '两': 2, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8}
    m = re.search(r'全片只有下面(.)句英语台词', t)
    if not m: loi.append('thiếu câu khoá thoại')
    elif so.get(m.group(1)) != len(can): loi.append(f'câu khoá ghi {m.group(1)} câu, kịch bản {len(can)}')
    # mã ảnh
    ngoai = re.sub(r'\{[^{}]*\}', '', t)
    for ten, so_anh in re.findall(r'([A-Z][A-Z0-9_]*)（@图片(\d+)）', ngoai):
        k = int(so_anh)
        if k < 1 or k > len(refs): loi.append(f'{ten}（@图片{k}）: không có ảnh thứ {k}'); continue
        r = refs[k - 1]
        hop = r == ten or r.startswith(f'SHEET_{ten}_') or r == f'PROP_{ten}' or r == f'LOC_{ten}'
        if not hop: loi.append(f'{ten}（@图片{k}） nhưng ảnh {k} là {r}')
    tron = re.findall(r'(?<![A-Z_])(' + '|'.join(TEN) + r')(?![A-Z_]|（@图片)', ngoai)
    if tron: loi.append(f'tên trơn không mã: {sorted(set(tron))}')
    # mốc giây
    moc = [(int(a), int(b)) for a, b in re.findall(r'\[(\d+)[–\-](\d+)秒\]', t)]
    if not moc: loi.append('không có mốc [a–b秒]')
    else:
        if moc[0][0] != 0 or moc[-1][1] != 30: loi.append(f'mốc không phủ 0–30: {moc[0]}…{moc[-1]}')
        for (a, b), (c, d) in zip(moc, moc[1:]):
            if b != c: loi.append(f'hở/chồng mốc {b}≠{c}')
    # chữ cấm
    for w in CAM:
        if w in ngoai: loi.append(f'chữ cấm {w}')
    if re.search(r'打(?!乱)', ngoai): loi.append('chữ 打')
    if any(r.startswith('SHEET_BIANCA') for r in refs):
        for w in CAM_BIANCA:
            if w in ngoai: loi.append(f'chữ cấm (trang phục Bianca) {w}')
    if '"' in ngoai or '“' in ngoai: canh.append('còn ngoặc kép ngoài thoại')
    nc, nb = len(t), len(t.encode('utf-8'))
    if nc < 1500 or nc > 5000: canh.append(f'độ dài {nc} ký tự')
    if nb > 14500: loi.append(f'{nb} byte > 14500')
    return loi, canh


def main():
    kb = thoai_kich_ban()
    ds = [int(x) for x in sys.argv[1:]] or list(range(1, 71))
    tong = 0
    for n in ds:
        loi, canh = soat(n, kb)
        if loi or canh:
            tong += bool(loi)
            print(f'cụm {n:02d}: ' + ('LỖI ' + ' | '.join(loi) if loi else '') + (' · cảnh báo: ' + ', '.join(canh) if canh else ''))
    print(f'— {len(ds) - tong}/{len(ds)} bài 0 lỗi')


if __name__ == '__main__':
    main()

