TEN = ['BEVERLY', 'AYANNA', 'DARIUS', 'BIANCA', 'EARNESTINE', 'CHARLENE', 'NADINE', 'TAMIA', 'LATASHA', 'IMES',
       'DRIVER', 'OFFICER', 'LOCKSMITH']
KHOI = ['参考图识别说明', '【场景图】', '【人物参考图】', '【人物位置】', '30秒', '镜头语言', '[保持不变]', '结尾时']
CAM = ['血', '枪', '杀', '暴力', '性感', '低胸', '胸']
CAM_BIANCA = ['抹胸', '露肩', '身材', '曲线', '紧身', '包臀', '迷你', '短裙', '大腿', '臀']


def thoai_kich_ban():
    t = KB.read_text(encoding='utf-8')
    ra = {}
    for b in re.split(r'^(?=#### Cụm )', t, flags=re.M):
        m = re.match(r'#### Cụm (\d+)', b)
        if not m: continue
        ra[int(m.group(1))] = [x for x in re.findall(r'^- \*\*[A-Z][A-Z .\'-]*?:?\*\*[^"\n]*"(.+)"\s*$', b, flags=re.M)]
    return ra


def chuan(s):
    return s.replace('’', "'").replace('‘', "'").replace('“', '"').replace('”', '"').replace('…', '...').strip()


